package com.sistema.despertar;
import android.content.BroadcastReceiver;import android.content.Context;import android.content.Intent;import android.app.NotificationManager;import android.app.NotificationChannel;import android.app.Notification;import android.app.PendingIntent;import android.os.Build;import java.util.Calendar;
public class ReminderReceiver extends BroadcastReceiver {
 private static final String CHANNEL="sistema_missions";
 @Override public void onReceive(Context c,Intent i){String action=i.getAction();String title=i.getStringExtra(ReminderScheduler.EXTRA_TITLE);if(title==null||title.trim().isEmpty())title="Recordatorio del Sistema";if(ReminderScheduler.ACTION_SNOOZE.equals(action)){ReminderScheduler.snooze(c,i.getStringExtra(ReminderScheduler.EXTRA_ID),title);return;}if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;if(!ReminderScheduler.ACTION_SNOOZED.equals(action)){Calendar now=Calendar.getInstance();int mask=i.getIntExtra(ReminderScheduler.EXTRA_DAYMASK,127),day=now.get(Calendar.DAY_OF_WEEK)-1;if((mask&(1<<day))==0)return;if(("water-repeat".equals(i.getStringExtra(ReminderScheduler.EXTRA_ID))||"stretch-repeat".equals(i.getStringExtra(ReminderScheduler.EXTRA_ID)))&&(now.get(Calendar.HOUR_OF_DAY)<8||now.get(Calendar.HOUR_OF_DAY)>21))return;}NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(CHANNEL,"Recordatorios de SISTEMA",NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription("Avisos de misiones y pausas activas");nm.createNotificationChannel(ch);}Intent open=new Intent(c,MainActivity.class);open.setFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent content=PendingIntent.getActivity(c,1,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent snooze=new Intent(c,ReminderReceiver.class);snooze.setAction(ReminderScheduler.ACTION_SNOOZE);snooze.putExtra(ReminderScheduler.EXTRA_ID,i.getStringExtra(ReminderScheduler.EXTRA_ID));snooze.putExtra(ReminderScheduler.EXTRA_TITLE,title);PendingIntent snoozePi=PendingIntent.getBroadcast(c,("sn_"+i.getStringExtra(ReminderScheduler.EXTRA_ID)).hashCode(),snooze,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("SISTEMA · Recordatorio").setContentText(title).setAutoCancel(true).setCategory(Notification.CATEGORY_REMINDER).setContentIntent(content).addAction(android.R.drawable.ic_menu_recent_history,"Posponer 10 min",snoozePi);nm.notify(title.hashCode(),b.build());}
}
